import assert from 'node:assert/strict'
import { test } from 'node:test'
import { findViolations } from '../lib/attribution.mjs'

const flagged = [
  '🤖 Generated with [Claude Code](https://claude.com/claude-code)',
  'Generated with Claude Code',
  '> *Generated by GPT-4o*',
  '- Created with the help of ChatGPT',
  'Written by an AI assistant',
  'Made with Cursor',
  'Assisted by Copilot',
  'Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>',
  'Co-authored-by: Copilot <175728472+Copilot@users.noreply.github.com>',
  'Co-authored-by: dependabot[bot] <49699333+dependabot[bot]@users.noreply.github.com>',
  'Co-authored-by: Cursor Agent <cursoragent@cursor.com>',
  'Co-authored-by: Some Vendor <noreply@vendor.example>',
  'Assisted-by: Claude',
  'Generated-by: some-tool',
  'Signed-off-by: Claude <noreply@anthropic.com>',
  'Claude-Session: https://claude.ai/code/session_01abc',
  'See https://claude.ai/code/session_01abc',
]

const allowed = [
  'Add support for claude-opus-5-5',
  'Reject Co-Authored-By trailers in CI',
  '- Reject Co-authored-by lines that name a tool.',
  'Generated files are now ignored by the linter.',
  'Code generated by protoc-gen-go. DO NOT EDIT.',
  'Generated with protoc',
  'Created by Alex Rivera',
  'Co-authored-by: Alex Rivera <alex@example.com>',
  'Co-authored-by: Devin Smith <devin@example.com>',
  'Co-authored-by: Claude Dupont <claude@example.com>',
  'Co-authored-by: Kai Tan <12345+kaitan@users.noreply.github.com>',
  'Signed-off-by: Alex Rivera <alex@example.com>',
  'Signed-off-by: dependabot[bot] <support@github.com>',
  'Copilot support is now documented.',
  'Add cursor pagination to the list endpoint',
  '',
]

for (const line of flagged) {
  test(`flags: ${line}`, () => {
    assert.equal(findViolations(line).length, 1)
  })
}

for (const line of allowed) {
  test(`allows: ${line || '(empty)'}`, () => {
    assert.deepEqual(findViolations(line), [])
  })
}

test('reports the line number inside a multi-line message', () => {
  const message = [
    'Fix the redirect loop',
    '',
    '- Keep the path on the 301.',
    '',
    'Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>',
  ].join('\n')
  const hits = findViolations(message)
  assert.equal(hits.length, 1)
  assert.equal(hits[0].line, 5)
})

test('handles CRLF line endings', () => {
  const hits = findViolations('Fix it\r\n\r\n🤖 Generated with Claude Code\r\n')
  assert.equal(hits.length, 1)
  assert.equal(hits[0].line, 3)
})
